/**
 * Persian (fa) translations.
 * Keys are the exact English strings used in the UI; values are the Persian text.
 * Placeholders like {name} are filled in by t(key, vars).
 */

const DIGITS = "۰۱۲۳۴۵۶۷۸۹";

/** Convert Latin digits (and , %) to their Persian forms. */
export function toFaDigits(input: string | number): string {
  return String(input)
    .replace(/[0-9]/g, (d) => DIGITS[Number(d)])
    .replace(/,/g, "٬")
    .replace(/%/g, "٪");
}

/** Strings with numbers inside (prices, durations, relative dates) are handled by patterns. */
export const faPatterns: Array<[RegExp, (m: RegExpMatchArray) => string]> = [
  [/^Too many attempts\. Try again in (\d+)s\.$/, (m) => `تلاش‌های ناموفق زیاد بود. ${toFaDigits(m[1])} ثانیه دیگر دوباره امتحان کنید.`],
  [/^\$([\d,]+) stipend$/, (m) => `${toFaDigits(m[1])} دلار کمک‌هزینه`],
  [/^(\d+) weeks?$/, (m) => `${toFaDigits(m[1])} هفته`],
  [/^(\d+) days? ago$/, (m) => `${toFaDigits(m[1])} روز پیش`],
  [/^(\d+) weeks? ago$/, (m) => `${toFaDigits(m[1])} هفته پیش`],
  [
    /^€([\d,]+)(?:–([\d,]+))? \/ (hour|month|year)$/,
    (m) => {
      const unit = { hour: "ساعت", month: "ماه", year: "سال" }[m[3] as "hour" | "month" | "year"];
      const amount = m[2] ? `${toFaDigits(m[1])} تا ${toFaDigits(m[2])} یورو` : `${toFaDigits(m[1])} یورو`;
      return `${amount} در ${unit}`;
    },
  ],
];

